<main class="google-workspace" data-youtube-actions>
<header class="pub-heading"><h1>YouTube channel studio</h1><p>Prepare one channel action, review its exact content and destination, then apply it once. Existing upload and audience-report connections are separate.</p></header>
<?php if($error!==''):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif;?>
<?php if($part==='new'):?>
<section class="pub-card"><h2>Prepare an action</h2><p>Preparation reads only the selected channel records. Applying an action uses YouTube API quota and may change what viewers see. Provider eligibility and quota restrictions still apply.</p>
<form method="get"><label for="yta-kind">Action</label><select id="yta-kind" name="kind"><?php foreach(yta_types()as$key=>$label):?><option value="<?=e($key)?>" <?=($values['kind']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><button class="wbtn">Choose action</button></form>
<?php $kind=isset(yta_types()[$values['kind']??''])?$values['kind']:'playlist';?>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="prepare"><input type="hidden" name="kind" value="<?=e($kind)?>">
<?php if($kind==='playlist'):?>
<label>Playlist title <input name="title" maxlength="150" required value="<?=e($values['title']??'')?>"></label>
<label>Description · up to 5,000 UTF-8 bytes <textarea name="description" maxlength="5000" rows="6"><?=e($values['description']??'')?></textarea></label>
<label for="yta-privacy">Visibility</label><select id="yta-privacy" name="privacy"><?php foreach(['private'=>'Private','unlisted'=>'Unlisted · anyone with the link','public'=>'Public']as$key=>$label):?><option value="<?=$key?>" <?=($values['privacy']??'private')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select>
<?php else:?>
<?php if($kind!=='moderate'):?><label>Owned video ID <input name="video" pattern="[A-Za-z0-9_-]{11}" required value="<?=e($values['video']??'')?>"><span>Use the 11-character ID from your video URL. The channel must own the video.</span></label><?php endif;?>
<?php if($kind==='playlist_item'):?><label>Owned playlist ID <input name="playlist" maxlength="200" required value="<?=e($values['playlist']??'')?>"></label><p>The selected video will be appended once. Preparation displays the playlist’s current title and visibility.</p>
<?php elseif($kind==='caption'):?>
<label>Caption language <input name="language" maxlength="35" placeholder="en, en-KE or sw" required value="<?=e($values['language']??'')?>"></label>
<label>Track name <input name="name" maxlength="100" required value="<?=e($values['name']??'')?>"></label>
<label for="yta-draft">Visibility</label><select id="yta-draft" name="draft"><option value="1" <?=($values['draft']??'1')==='1'?'selected':''?>>Draft · hidden from viewers</option><option value="0" <?=($values['draft']??'1')==='0'?'selected':''?>>Visible when YouTube finishes processing</option></select>
<label>Timed SRT · up to 100,000 UTF-8 bytes and 1,000 cues <textarea name="text" rows="14" maxlength="100000" required placeholder="1&#10;00:00:01,000 --&gt; 00:00:03,000&#10;Your caption text."><?=e($values['text']??'')?></textarea></label><p>Supply your own timed captions. Existing tracks are preserved. This does not activate recording, transcription, translation or automatic synchronisation.</p>
<?php elseif($kind==='thumbnail'):?>
<label for="yta-asset">Media-library image</label><select id="yta-asset" name="asset" required><option value="">Choose an image</option><?php foreach($assets as$asset):?><option value="<?=(int)$asset['id']?>" <?=($values['asset']??'')===(string)$asset['id']?'selected':''?>><?=e($asset['title'].' · '.$asset['mime'].' · '.$asset['bytes'].' bytes')?></option><?php endforeach;?></select><p>Use a ready JPEG or PNG of at most 2 MiB and 4096 pixels in either direction. <a href="<?=url('/write/media')?>">Open the media library</a>. Custom thumbnails require channel eligibility. YouTube may transform the image and delay its display.</p>
<?php elseif($kind==='moderate'):?>
<label>Comment ID <input name="comment" maxlength="200" required value="<?=e($values['comment']??'')?>"></label>
<label for="yta-moderation">Outcome</label><select id="yta-moderation" name="moderation"><?php foreach(['published'=>'Publish the comment','heldForReview'=>'Hold for review where supported','rejected'=>'Reject and hide replies']as$key=>$label):?><option value="<?=$key?>" <?=($values['moderation']??'')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><p>One comment only. Its text and current state are shown before approval. Rejection hides replies and cannot be undone here; YouTube does not allow republishing a rejected comment through this API. The author is never automatically banned.</p>
<?php endif;?>
<?php endif;?>
<label class="pub-check"><input type="checkbox" name="content_consent" value="1" required> Read these selected channel records and prepare the specified content for my review.</label><button class="wbtn primary">Prepare preview</button></form><p><a href="<?=url('/write/google/youtube')?>">Back to channel studio</a></p></section>
<?php elseif($record):?>
<section class="pub-card"><h2><?=e(yta_types()[$record['kind']])?></h2>
<dl><dt>State</dt><dd><?=e(str_replace('_',' ',$record['state']))?></dd><dt>Confirmed account</dt><dd><?=e($record['account'])?></dd><dt>Selected channel</dt><dd><?=e($record['channel'])?></dd><dt>Prepared</dt><dd><?=e(gmdate('j M Y H:i',$record['created_at']).' UTC')?></dd></dl>
<?php foreach($record['source']as$key=>$source):if($key==='tracks')continue;?><h3><?=e(ucfirst($key).' selected for this action')?></h3><dl><?php foreach($source as$field=>$value):if($field==='etag')continue;?><dt><?=e(ucfirst($field))?></dt><dd><?=e($value)?></dd><?php endforeach;?></dl><?php endforeach;?>
<h3>Exact proposed change</h3><dl><?php foreach($record['payload']as$field=>$value):if(in_array($field,['asset','text'],true))continue;?><dt><?=e(ucfirst($field))?></dt><dd><?=e(is_bool($value)?($value?'Yes':'No'):$value)?></dd><?php endforeach;?></dl>
<?php if($record['kind']==='caption'):?><pre class="youtube-action-text"><?=e($record['payload']['text'])?></pre><?php endif;?>
<?php if($record['kind']==='thumbnail'):?><p>This exact image will be sent to YouTube and displayed according to the video’s visibility shown above, including when its media-library copy is private.</p><img class="youtube-action-image" src="<?=url('/write/google/youtube/'.$record['id'].'/image')?>" alt="Exact media-library thumbnail selected for this action"><p><?=e($record['payload']['asset']['title'])?> · <?=e($record['payload']['asset']['bytes'])?> bytes</p><?php endif;?>
<?php if($record['kind']==='moderate'&&$record['payload']['moderation']==='rejected'):?><p><strong>Rejection hides this comment and its replies. It cannot be undone here.</strong> API acknowledgement is recorded separately from independent verification in Studio.</p><?php endif;?>
<p>Reviews expire after 30 minutes. Each apply request uses provider quota; playlist creation, playlist entries, thumbnails and moderation each cost about 50 units. Caption upload costs 400 units; caption listing costs 50 units and caption download for verification costs 200 units. Source checks and rechecks consume additional quota. No credits or paid products are purchased here.</p>
<?php if(!empty($record['outcome'])):?><p role="status"><?=e($record['outcome'])?></p><?php endif;?>
<?php if(!empty($record['verification'])):?><p><?=e($record['verification'])?></p><?php endif;?>
<?php if(!empty($record['url'])):?><p><a class="wbtn" href="<?=e($record['url'])?>" target="_blank" rel="noopener noreferrer">Open YouTube result ↗</a></p><?php endif;?>
<?php if(in_array($record['state'],['draft','reviewed'],true)):?>
<form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><input type="hidden" name="action" value="<?=$record['state']==='draft'?'review':'apply'?>"><label class="pub-check"><input type="checkbox" name="confirm" value="1" required> <?=$record['state']==='draft'?'I have reviewed the displayed channel, source, visibility and exact proposed change.':'Apply this exact change to the displayed YouTube channel now.'?></label><button class="wbtn primary"><?=$record['state']==='draft'?'Confirm review':'Apply to YouTube'?></button></form>
<?php if($record['state']==='reviewed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><input type="hidden" name="action" value="review"><label class="pub-check"><input type="checkbox" name="confirm" value="1" required> I have reviewed this exact action again.</label><button class="wbtn">Renew review</button></form><?php endif;?>
<form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><button class="wbtn" name="action" value="discard">Discard unused action</button></form>
<?php endif;?>
<?php if(in_array($record['state'],['unknown','verification_pending','done'],true)&&!empty($record['remote_id'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$record['version']?>"><button class="wbtn" name="action" value="recheck">Read existing result</button><p>This checks the known result without repeating the change.</p></form><?php endif;?>
<?php if(in_array($record['state'],['acknowledged','executing','unknown'],true)):?><p><a href="https://studio.youtube.com/" target="_blank" rel="noopener noreferrer">Review YouTube Studio ↗</a>. Keep this record as evidence before preparing a replacement.</p><?php endif;?>
<details><summary>Action history</summary><ol><?php foreach($record['audit']as$entry):?><li><?=e(gmdate('j M Y H:i',$entry['at']).' UTC · '.str_replace('_',' ',$entry['state']))?></li><?php endforeach;?></ol></details><p><a href="<?=url('/write/google/youtube')?>">All YouTube actions</a></p></section>
<?php else:?>
<section class="pub-card"><h2>Channel actions</h2><p>Manage selected content on your own channel. YouTube channel management requires a separate Google grant; read-only reports and upload access do not establish it.</p><a class="wbtn primary" href="<?=url('/write/google/youtube/new')?>">Prepare a channel action</a></section>
<section class="pub-card"><h2>Connection</h2><?php try{$connection=yta_ready($uid);?><p>Confirmed account: <?=e($connection['display_name'])?>. Channel: <?=e($connection['selected_resource'])?>.</p><?php }catch(YouTubeActionException $connectionError){?><p><?=e($connectionError->getMessage())?></p><?php }?><a href="<?=url('/write/connections#google_youtube_manage')?>">Review channel-management connection</a></section>
<section class="pub-card"><h2>Your actions</h2><?php if(!$records):?><p>No channel actions prepared yet.</p><?php endif;?><?php foreach($records as$row):?><article class="youtube-action-row"><h3><a href="<?=url('/write/google/youtube/'.$row['id'])?>"><?=e($row['title'])?></a></h3><p><?=e(yta_types()[$row['kind']].' · '.str_replace('_',' ',$row['state']))?></p></article><?php endforeach;?></section>
<?php endif;?></main>
